n = int(2, 10)
a = distinct(n, 1, 50)
# w połowie testów k jest sumą dwóch elementów tablicy
if chance(0.5) {
    k = a[0] + a[1]
} else {
    k = int(2, 100)
}
print n, k
print shuffle(a)

tests 500
n = int(1, 15)
kind = int(1, 3)
if kind == 1 {
    s = palindrome(n, "abc")
} elif kind == 2 {
    s = periodic(n, int(1, 4), "abc")
} else {
    s = string(n, "abc")
}
print n
print s

